 static final String BG_CHANNEL="mada_bg",BUZZ_CHANNEL="mada_buzz_high";
 OkHttpClient client;WebSocket ws;WindowManager wm;View overlay;String uid,token,refresh,lastBuzzAt="";SharedPreferences sp;Handler h=new Handler(Looper.getMainLooper());boolean reconnecting=false,polling=false;int joinRef=0;final HashSet<String> seenBuzz=new HashSet<>();
 Runnable refreshTask=()->refreshSession();Runnable heartbeat=()->sendHeartbeat();Runnable pollTask=()->pollBuzzes();
 @Override public void onCreate(){super.onCreate();sp=getSharedPreferences("mada",0);client=new OkHttpClient.Builder().connectTimeout(15,TimeUnit.SECONDS).readTimeout(0,TimeUnit.MILLISECONDS).writeTimeout(15,TimeUnit.SECONDS).pingInterval(25,TimeUnit.SECONDS).build();createChannels();startForegroundCompat("جاري تشغيل حماية Buzz...");loadCredentials();initPollCursor();connect();}
 void startForegroundCompat(String text){Notification n=notification(text);if(Build.VERSION.SDK_INT>=34)startForeground(7,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_REMOTE_MESSAGING);else startForeground(7,n);}
 Notification notification(String text){Intent i=new Intent(this,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(this,0,i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,BG_CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Mada Buzz").setContentText(text).setContentIntent(pi).setOngoing(true).build();}
 void updateNotification(String text){try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7,notification(text));}catch(Exception ignored){}}
 void createChannels(){if(Build.VERSION.SDK_INT>=26){NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel(BG_CHANNEL,"Mada Buzz",NotificationManager.IMPORTANCE_LOW));NotificationChannel b=new NotificationChannel(BUZZ_CHANNEL,"Buzz",NotificationManager.IMPORTANCE_HIGH);b.setDescription("تنبيهات Buzz المنبثقة");b.enableVibration(true);b.setVibrationPattern(new long[]{0,180,70,180,70,320});b.setLockscreenVisibility(Notification.VISIBILITY_PUBLIC);n.createNotificationChannel(b);}}
 void loadCredentials(){token=sp.getString("access","");refresh=sp.getString("refresh","");uid=sp.getString("uid","");}
 void connect(){loadCredentials();if(TextUtils.isEmpty(token)||TextUtils.isEmpty(uid)){updateNotification("افتح Mada لتفعيل Buzz");return;}reconnecting=false;HttpUrl u=HttpUrl.parse(URL+"/realtime/v1/websocket").newBuilder().addQueryParameter("apikey",KEY).addQueryParameter("vsn","1.0.0").build();Request r=new Request.Builder().url(u).build();ws=client.newWebSocket(r,new WebSocketListener(){@Override public void onOpen(WebSocket s,Response r){try{joinRef++;JSONObject cfg=new JSONObject();cfg.put("broadcast",new JSONObject().put("ack",false).put("self",false));cfg.put("presence",new JSONObject().put("enabled",false));cfg.put("postgres_changes",new JSONArray().put(new JSONObject().put("event","INSERT").put("schema","public").put("table","messages").put("filter","message_type=eq.buzz")));JSONObject payload=new JSONObject().put("config",cfg).put("access_token",token);String jr=String.valueOf(joinRef);JSONObject join=new JSONObject().put("topic","realtime:public:messages").put("event","phx_join").put("payload",payload).put("ref",jr).put("join_ref",jr);s.send(join.toString());h.removeCallbacks(heartbeat);h.postDelayed(heartbeat,20000);scheduleRefresh();updateNotification("Buzz يعمل في الخلفية");}catch(Exception e){updateNotification("تعذر الاتصال بخدمة Buzz");scheduleReconnect();}}
 @Override public void onMessage(WebSocket s,String text){try{JSONObject x=new JSONObject(text);String ev=x.optString("event");if("phx_reply".equals(ev)){JSONObject p=x.optJSONObject("payload");if(p!=null&&"error".equals(p.optString("status"))){updateNotification("Realtime رفض الاتصال — يعمل الفحص التلقائي");scheduleReconnect();}return;}if("system".equals(ev)){JSONObject p=x.optJSONObject("payload");if(p!=null&&"error".equals(p.optString("status")))updateNotification("Realtime غير متصل — يعمل الفحص التلقائي");return;}if("phx_close".equals(ev)||"phx_error".equals(ev)){scheduleReconnect();return;}if(!"postgres_changes".equals(ev))return;JSONObject p=x.optJSONObject("payload");if(p==null)return;JSONObject data=p.optJSONObject("data");JSONObject row=data!=null?data.optJSONObject("record"):p.optJSONObject("record");if(row==null)return;if(!"buzz".equals(row.optString("message_type")))return;if(uid.equals(row.optString("sender_id")))return;String id=row.optString("id","");if(!rememberBuzz(id))return;markBuzzSeen(row.optString("created_at",""));showOverlay(row.optString("sender_id"));}catch(Exception ignored){}}
 @Override public void onFailure(WebSocket s,Throwable t,Response r){updateNotification("انقطع اتصال Buzz — يعمل الفحص التلقائي");scheduleReconnect();}});}
 boolean rememberBuzz(String id){if(TextUtils.isEmpty(id))return true;synchronized(seenBuzz){if(seenBuzz.contains(id))return false;seenBuzz.add(id);if(seenBuzz.size()>300){Iterator<String> it=seenBuzz.iterator();if(it.hasNext()){it.next();it.remove();}}return true;}}
 void sendHeartbeat(){if(ws!=null){try{ws.send(new JSONObject().put("topic","phoenix").put("event","heartbeat").put("payload",new JSONObject()).put("ref",String.valueOf(System.currentTimeMillis())).toString());}catch(Exception ignored){}}h.postDelayed(heartbeat,20000);}
 void scheduleReconnect(){if(reconnecting)return;reconnecting=true;h.removeCallbacks(heartbeat);h.postDelayed(()->{reconnecting=false;if(ws!=null){try{ws.close(1000,"reconnect");}catch(Exception ignored){}}ws=null;connect();},5000);}
 void scheduleRefresh(){h.removeCallbacks(refreshTask);h.postDelayed(refreshTask,45*60*1000L);}
 void refreshSession(){loadCredentials();if(TextUtils.isEmpty(refresh)){scheduleRefreshRetry();return;}String encoded;try{encoded=java.net.URLEncoder.encode(refresh,"UTF-8");}catch(Exception e){scheduleRefreshRetry();return;}RequestBody body=RequestBody.create("grant_type=refresh_token&refresh_token="+encoded,MediaType.parse("application/x-www-form-urlencoded"));Request req=new Request.Builder().url(URL+"/auth/v1/token?grant_type=refresh_token").post(body).addHeader("apikey",KEY).addHeader("Content-Type","application/x-www-form-urlencoded").build();client.newCall(req).enqueue(new Callback(){public void onFailure(Call c,java.io.IOException e){scheduleRefreshRetry();}public void onResponse(Call c,Response r)throws java.io.IOException{try{String text=r.body()!=null?r.body().string():"";if(!r.isSuccessful())throw new Exception("refresh "+r.code());JSONObject o=new JSONObject(text);String a=o.optString("access_token","");String rr=o.optString("refresh_token",refresh);if(TextUtils.isEmpty(a))throw new Exception("missing access token");token=a;refresh=rr;sp.edit().putString("access",a).putString("refresh",rr).apply();if(ws!=null)ws.close(1000,"token refresh");ws=null;connect();}catch(Exception e){scheduleRefreshRetry();}}});}
 void scheduleRefreshRetry(){h.removeCallbacks(refreshTask);h.postDelayed(refreshTask,5*60*1000L);}
 void initPollCursor(){long start=System.currentTimeMillis()-30000L;lastBuzzAt=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US).format(new Date(start));h.removeCallbacks(pollTask);h.post(pollTask);}
 void pollBuzzes(){if(polling){h.postDelayed(pollTask,3000);return;}polling=true;loadCredentials();if(TextUtils.isEmpty(token)||TextUtils.isEmpty(uid)){polling=false;h.postDelayed(pollTask,3000);return;}try{HttpUrl u=HttpUrl.parse(URL+"/rest/v1/messages").newBuilder().addQueryParameter("select","id,sender_id,created_at,message_type").addQueryParameter("message_type","eq.buzz").addQueryParameter("sender_id","neq."+uid).addQueryParameter("created_at","gt."+lastBuzzAt).addQueryParameter("order","created_at.asc").addQueryParameter("limit","50").build();Request r=new Request.Builder().url(u).addHeader("apikey",KEY).addHeader("Authorization","Bearer "+token).build();client.newCall(r).enqueue(new Callback(){public void onFailure(Call c,java.io.IOException e){polling=false;h.postDelayed(pollTask,3000);}public void onResponse(Call c,Response r)throws java.io.IOException{try{String text=r.body()!=null?r.body().string():"[]";if(r.isSuccessful()){JSONArray a=new JSONArray(text);for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);String at=row.optString("created_at",lastBuzzAt);if(!TextUtils.isEmpty(at)&&at.compareTo(lastBuzzAt)>0)lastBuzzAt=at;String sender=row.optString("sender_id","");String id=row.optString("id","");if(!TextUtils.isEmpty(sender)&&!uid.equals(sender)&&rememberBuzz(id))showOverlay(sender);}}else if(r.code()==401){refreshSession();}}catch(Exception ignored){}polling=false;h.postDelayed(pollTask,3000);}});}catch(Exception e){polling=false;h.postDelayed(pollTask,3000);}}
 void markBuzzSeen(String at){if(!TextUtils.isEmpty(at)&&at.compareTo(lastBuzzAt)>0)lastBuzzAt=at;}
 void showOverlay(String senderId){h.post(()->{if(Build.VERSION.SDK_INT>=23&&!Settings.canDrawOverlays(this))return;String name="صديق Mada";postBuzzNotification(name,senderId);try{Request r=new Request.Builder().url(URL+"/rest/v1/profiles?id=eq."+senderId+"&select=display_name").addHeader("apikey",KEY).addHeader("Authorization","Bearer "+token).build();client.newCall(r).enqueue(new Callback(){public void onFailure(Call c,java.io.IOException e){drawOverlay(name,senderId);}public void onResponse(Call c,Response r)throws java.io.IOException{String n=name;try{String text=r.body()!=null?r.body().string():"[]";JSONArray a=new JSONArray(text);if(a.length()>0){String q=a.getJSONObject(0).optString("display_name","");if(!TextUtils.isEmpty(q))n=q;}}catch(Exception ignored){}drawOverlay(n,senderId);}});}catch(Exception e){drawOverlay(name,senderId);}});}
 void postBuzzNotification(String name,String senderId){try{Intent i=new Intent(this,MainActivity.class);i.putExtra("sender_id",senderId);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(this,Math.abs(senderId.hashCode()),i,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(this,BUZZ_CHANNEL).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Mada — Buzz 📳").setContentText(name+" أرسل لك Buzz").setPriority(Notification.PRIORITY_MAX).setAutoCancel(true).setContentIntent(pi).setCategory(Notification.CATEGORY_MESSAGE).setVibrate(new long[]{0,180,70,180,70,320});if(Build.VERSION.SDK_INT<26)b.setDefaults(Notification.DEFAULT_SOUND|Notification.DEFAULT_VIBRATE);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()&0x7fffffff),b.build());}catch(Exception ignored){}}
 void drawOverlay(String name,String senderId){h.post(()->{if(Build.VERSION.SDK_INT>=23&&!Settings.canDrawOverlays(this)){updateNotification("اسمح لـ Mada بالظهور فوق التطبيقات");return;}removeOverlay();wm=(WindowManager)getSystemService(WINDOW_SERVICE);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(28,24,28,24);card.setGravity(Gravity.CENTER_HORIZONTAL);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setStroke(5,Color.rgb(245,158,11));bg.setCornerRadius(28);card.setBackground(bg);TextView head=new TextView(this);head.setText(name+"\n\nأرسل لك Buzz 📳");head.setTextColor(Color.rgb(20,35,60));head.setTextSize(24);head.setGravity(Gravity.CENTER);head.setTypeface(null,1);card.addView(head,new LinearLayout.LayoutParams(-1,-2));TextView body=new TextView(this);body.setText("📳\n\nهـــزّك صديقك في Mada!");body.setTextColor(Color.rgb(55,65,81));body.setTextSize(20);body.setGravity(Gravity.CENTER);body.setPadding(0,25,0,25);card.addView(body,new LinearLayout.LayoutParams(-1,-2));Button open=new Button(this);open.setText("فتح المحادثة");open.setTextSize(18);open.setTextColor(Color.WHITE);GradientDrawable ob=new GradientDrawable();ob.setColor(Color.rgb(245,158,11));ob.setCornerRadius(20);open.setBackground(ob);open.setOnClickListener(v->{removeOverlay();Intent i=new Intent(this,MainActivity.class);i.putExtra("sender_id",senderId);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);});card.addView(open,new LinearLayout.LayoutParams(-1,80));card.setOnClickListener(v->{});overlay=card;WindowManager.LayoutParams p=new WindowManager.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.88f),WindowManager.LayoutParams.WRAP_CONTENT,Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,android.graphics.PixelFormat.TRANSLUCENT);p.gravity=Gravity.CENTER;try{wm.addView(card,p);}catch(Exception e){overlay=null;updateNotification("تعذر عرض نافذة Buzz — تأكد من إذن الظهور فوق التطبيقات");h.postDelayed(()->{if(overlay==null&&Settings.canDrawOverlays(this))drawOverlay(name,senderId);},1000);return;}AnimationSet shake=new AnimationSet(true);TranslateAnimation t=new TranslateAnimation(-10,10,0,0);t.setDuration(70);t.setRepeatMode(Animation.REVERSE);t.setRepeatCount(7);shake.addAnimation(t);card.startAnimation(shake);try{Vibrator v=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(Build.VERSION.SDK_INT>=26)v.vibrate(VibrationEffect.createWaveform(new long[]{0,180,70,180,70,320},-1));else v.vibrate(new long[]{0,180,70,180,70,320},-1);}catch(Exception ignored){}h.postDelayed(this::removeOverlay,9000);});}
 void removeOverlay(){if(wm!=null&&overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;}}
 @Override public int onStartCommand(Intent i,int f,int id){loadCredentials();if(ws==null)connect();if(lastBuzzAt.length()==0)initPollCursor();else h.post(pollTask);return START_STICKY;}
 @Override public void onTaskRemoved(Intent rootIntent){try{Intent i=new Intent(this,BuzzService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception ignored){}super.onTaskRemoved(rootIntent);}
